package ru.neverland.townyjobs;
import java.util.*;import org.bukkit.*;import org.bukkit.block.data.Ageable;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.event.inventory.*;
public final class JobsListener implements Listener {
    private final JobsService service;private final Map<UUID,Location> patrol=new HashMap<>();
    public JobsListener(JobsService service){this.service=service;}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void interact(PlayerInteractEvent e){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e.getHand()!=org.bukkit.inventory.EquipmentSlot.HAND||e.getAction()!=org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null||e.useInteractedBlock()==Event.Result.DENY)return;Material m=e.getClickedBlock().getType();Profession job=switch(m){case ANVIL,CHIPPED_ANVIL,DAMAGED_ANVIL,SMITHING_TABLE,BLAST_FURNACE,FURNACE->Profession.BLACKSMITH;case COMPOSTER,BEEHIVE,BEE_NEST,HAY_BLOCK->Profession.FARMER;case LEVER,DAYLIGHT_DETECTOR,REPEATER,COMPARATOR->Profession.ENGINEER;case CHEST,TRAPPED_CHEST,BARREL,CHISELED_BOOKSHELF->Profession.MERCHANT;case LECTERN,BOOKSHELF,ENCHANTING_TABLE,CARTOGRAPHY_TABLE->Profession.RESEARCHER;case BREWING_STAND,CAULDRON,WATER_CAULDRON->Profession.ALCHEMIST;default->null;};if(job!=null)service.signal(e.getPlayer().getUniqueId(),job);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void crop(BlockBreakEvent e){ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e.getBlock().getBlockData() instanceof Ageable a&&a.getAge()==a.getMaximumAge())service.signal(e.getPlayer().getUniqueId(),Profession.FARMER);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void breed(EntityBreedEvent e){ try (var suiteGuard3 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e.getBreeder() instanceof Player p)service.signal(p.getUniqueId(),Profession.FARMER);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void shear(PlayerShearEntityEvent e){ try (var suiteGuard4 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}service.signal(e.getPlayer().getUniqueId(),Profession.FARMER);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void place(BlockPlaceEvent e){ try (var suiteGuard5 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e.canBuild())service.signal(e.getPlayer().getUniqueId(),Profession.ENGINEER);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void smelt(FurnaceExtractEvent e){ try (var suiteGuard6 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e.getItemAmount()>0)service.signal(e.getPlayer().getUniqueId(),Profession.BLACKSMITH);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void craft(CraftItemEvent e){ try (var suiteGuard7 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(!(e.getWhoClicked() instanceof Player p)||e.getAction()==InventoryAction.NOTHING)return;String key=e.getRecipe().getResult().getType().name();if(key.startsWith("IRON_")||key.startsWith("GOLDEN_")||key.startsWith("COPPER_")||key.startsWith("NETHERITE_"))service.signal(p.getUniqueId(),Profession.BLACKSMITH);if(Set.of("BOOK","WRITABLE_BOOK","MAP","PAPER").contains(key))service.signal(p.getUniqueId(),Profession.RESEARCHER);if(Set.of("BREAD","CAKE","COOKIE","PUMPKIN_PIE").contains(key))service.signal(p.getUniqueId(),Profession.FARMER);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void brew(BrewEvent e){ try (var suiteGuard8 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}service.signalAt(e.getBlock(),Profession.ALCHEMIST);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void kill(EntityDeathEvent e){ try (var suiteGuard9 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}Player p=e.getEntity().getKiller();if(p!=null&&e.getEntity() instanceof Enemy)service.signal(p.getUniqueId(),Profession.GUARD);} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void move(PlayerMoveEvent e){ try (var suiteGuard10 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(e instanceof PlayerTeleportEvent||e.getTo()==null||service.career(e.getPlayer().getUniqueId()).profession()!=Profession.GUARD||!service.onDuty(e.getPlayer().getUniqueId()))return;Location old=patrol.get(e.getPlayer().getUniqueId());if(old==null||!old.getWorld().equals(e.getTo().getWorld())){patrol.put(e.getPlayer().getUniqueId(),e.getTo().clone());return;}if(old.distanceSquared(e.getTo())>=9){patrol.put(e.getPlayer().getUniqueId(),e.getTo().clone());service.signal(e.getPlayer().getUniqueId(),Profession.GUARD);}} }
    @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void protect(EntityDamageByEntityEvent e){ try (var suiteGuard11 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}if(!(e.getEntity() instanceof Player p))return;Entity source=e.getDamager();if(source instanceof Projectile projectile){if(!(projectile.getShooter() instanceof Entity shooter))return;source=shooter;}if(!(source instanceof Enemy))return;var town=service.town(p);var here=com.palmergames.bukkit.towny.TownyAPI.getInstance().getTown(p.getLocation());if(town==null||here==null||!town.getUUID().equals(here.getUUID()))return;e.setDamage(e.getDamage()*(1-service.townBonus(town.getUUID(),"guard_defence")));} }
    @EventHandler public void quit(PlayerQuitEvent e){ try (var suiteGuard12 = ru.neverland.core.SuiteState.guard()) {service.endShift(e.getPlayer().getUniqueId());patrol.remove(e.getPlayer().getUniqueId());} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void teleport(PlayerTeleportEvent e){ try (var suiteGuard13 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}service.endShift(e.getPlayer().getUniqueId());patrol.remove(e.getPlayer().getUniqueId());} }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void mode(PlayerGameModeChangeEvent e){ try (var suiteGuard14 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}service.endShift(e.getPlayer().getUniqueId());} }
    @EventHandler public void death(PlayerDeathEvent e){ try (var suiteGuard15 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyJobs")){ru.neverland.core.ModuleGate.stopEvent(e);return;}service.endShift(e.getPlayer().getUniqueId());} }
    @EventHandler public void left(com.palmergames.bukkit.towny.event.TownRemoveResidentEvent e){ try (var suiteGuard16 = ru.neverland.core.SuiteState.guard()) {service.removeResident(e.getResident().getUUID());} }
    @EventHandler public void deleted(com.palmergames.bukkit.towny.event.DeleteTownEvent e){ try (var suiteGuard17 = ru.neverland.core.SuiteState.guard()) {for(var row:service.repository().all().entrySet())if(e.getTownUUID().equals(row.getValue().town()))service.removeResident(row.getKey());} }
}
